'use strict';
(()=>{
if(new URLSearchParams(location.search).get('edit')!=='1')return;
let busy=false,logged=false;const progress=document.querySelector('#draft-status');
const dialog=document.createElement('dialog');dialog.className='publisher-dialog';dialog.innerHTML='<form><h2>本人发布登录</h2><p>登录后可将预览草稿更新到正式网站。</p><label>发布密码<input name="password" type="password" autocomplete="current-password" required maxlength="200"></label><p class="publisher-error" role="status"></p><div class="actions"><button type="button" data-cancel>取消</button><button type="submit">登录</button></div></form>';document.body.append(dialog);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();
async function request(path,options={}){const response=await fetch('/api/editor/'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await response.json();if(!response.ok)throw Error(data.error||'操作暂时失败，草稿仍保留。');return data;}
let resolveLogin;dialog.addEventListener('close',()=>{resolveLogin?.(false);resolveLogin=null;dialog.querySelector('input').value='';});
dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=dialog.querySelector('[type=submit]');button.disabled=true;try{await request('auth',{method:'POST',body:JSON.stringify({password:dialog.querySelector('input').value})});logged=true;document.querySelector('[data-draft=logout]').hidden=false;const done=resolveLogin;resolveLogin=null;dialog.close();done?.(true);}catch(error){dialog.querySelector('.publisher-error').textContent=error.message;}finally{button.disabled=false;}};
async function login(){const auth=await request('auth');if(auth.authenticated){logged=true;document.querySelector('[data-draft=logout]').hidden=false;return true;}dialog.querySelector('.publisher-error').textContent='';dialog.showModal();return new Promise(resolve=>resolveLogin=resolve);}
function delay(ms){return new Promise(resolve=>setTimeout(resolve,ms));}
window.editorPublisher={async login(){try{if(await login())progress.textContent='本人已登录，可以预览并发布草稿。';}catch(error){progress.textContent=error.message;}},async publish(){if(busy)return;document.activeElement?.blur();await window.publishedReady;const sent=window.portfolioDraft.getPatches();const pdfFile=window.portfolioPDF?.pending;if(!pdfFile&&!Object.values(sent).some(x=>Object.keys(x).length)){progress.textContent='没有新的草稿修改。';return;}busy=true;const button=document.querySelector('[data-draft=publish]');button.disabled=true;try{if(!await login())return;if(!document.body.classList.contains('draft-preview')){document.querySelector('[data-draft=preview]').click();progress.textContent='已进入预览，请检查后再次点击“一键发布”。';return;}if(!confirm('将当前预览的文字、图片、PDF 和删除修改发布到正式网站？'))return;let pdf;if(pdfFile)pdf=await uploadPDF(pdfFile);progress.textContent='正在提交修改…';const result=await request('publish',{method:'POST',body:JSON.stringify({patches:sent,baseRevision:window.publishedPortfolio.revision,...(pdf?{pdf}: {})})});sessionStorage.setItem('shilu-publishing',JSON.stringify({...result,sent,pdfDate:pdfFile?.date}));await waitReady({...result,pdfDate:pdfFile?.date},sent);}catch(error){progress.textContent=error.message;}finally{busy=false;button.disabled=false;}},async logout(){try{await request('auth',{method:'DELETE'});logged=false;document.querySelector('[data-draft=logout]').hidden=true;progress.textContent='已退出发布登录，草稿仍保留。';}catch(error){progress.textContent=error.message;}}};
async function uploadPDF(file){const id=crypto.randomUUID();const size=2*1024*1024;const count=Math.ceil(file.blob.size/size);const receipts=new Array(count);let next=0,finished=0;async function worker(){while(next<count){const index=next++;const part=file.blob.slice(index*size,(index+1)*size);const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(part);});let result;for(let attempt=0;attempt<3;attempt++){try{result=await request('pdf',{method:'POST',body:JSON.stringify({id,index,data})});break;}catch(error){if(attempt===2)throw error;await delay(1000);}}receipts[index]=result.receipt;finished++;progress.textContent='正在上传 PDF '+Math.round(finished/count*100)+'%';}}await Promise.all([worker(),worker()]);return {id,name:file.name,size:file.blob.size,receipts};}
async function waitReady(result,sent){progress.textContent='已提交 GitHub，正在等待正式网站更新…';for(let n=0;n<90;n++){await delay(4000);try{const r=await fetch('/published.json?deploy='+Date.now(),{cache:'no-store'});if(r.ok&&(await r.json()).revision===result.revision){sessionStorage.removeItem('shilu-publishing');if(result.pdfDate&&window.portfolioPDF?.pending?.date===result.pdfDate)await window.portfolioPDF.clearPublished();window.portfolioDraft.clearPublished(sent);progress.textContent='发布成功，正式网站已更新。';setTimeout(()=>location.reload(),1800);return;}}catch{}}progress.textContent='已提交，部署仍在进行。草稿已保留，稍后刷新会继续检查。';}
try{const pending=JSON.parse(sessionStorage.getItem('shilu-publishing')||'null');if(pending){busy=true;waitReady(pending,pending.sent).finally(()=>busy=false);}}catch{}
})();
